package org.sleepwell.app;
import android.content.*;import android.graphics.*;import android.os.Bundle;import android.text.*;import android.view.*;import android.widget.*;import java.util.function.BooleanSupplier;
/** Actual drawn-code entry, shared unchanged between quiet preview and the current alarm unit. */
final class TypeCodeTask implements AutoCloseable {
 final String key;final SharedPreferences prefs;final TypeCodePuzzle puzzle;final EditText input;final TextView feedback;final Button submit;final BooleanSupplier current;final Runnable complete,fallback;boolean closed;
 static String key(String run,int unit,int level){TypeCodePuzzle.length(level);return ChallengePackState.key(run,unit,level-1);}
 static boolean math(SharedPreferences p,String run,int unit,int level){return key(run,unit,level).equals(p.getString("typeCodeMathOwner",""));}
 TypeCodeTask(LinearLayout body,SharedPreferences prefs,String run,int unit,int level,Bundle restored,BooleanSupplier current,Runnable complete,Runnable fallback){this.prefs=prefs;this.current=current;this.complete=complete;this.fallback=fallback;key=key(run,unit,level);puzzle=new TypeCodePuzzle(run,unit,level);Design.text(body,"Type the code",22,600,Design.INK);Design.text(body,"Letters and digits · case does not matter",13,400,Design.MUTED);Design.space(body,12);body.addView(new CodeArt(body.getContext(),puzzle),new LinearLayout.LayoutParams(-1,Design.dp(body.getContext(),116)));Design.space(body,16);input=new EditText(body.getContext());input.setContentDescription("Challenge code answer");input.setSingleLine(true);input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);input.setTextSize(24*Appearance.scale(body.getContext()));input.setTypeface(Design.font(body.getContext(),600));input.setTextColor(Design.INK);input.setBackground(Design.outline(body.getContext(),Design.SOFT,Design.LINE,14));Design.pad(input,16,12);input.setFilters(new InputFilter[]{new InputFilter.AllCaps(),new InputFilter.LengthFilter(8)});if(restored!=null&&key.equals(restored.getString("typeCodeKey")))input.setText(restored.getString("typeCodeAnswer",""));body.addView(input,new LinearLayout.LayoutParams(-1,-2));feedback=Design.text(body,"",13,500,Design.BROWN);submit=Design.button(body,"Check code",true,()->{if(closed||!current.getAsBoolean())return;if(puzzle.accepts(input.getText().toString())){closed=true;complete.run();}else feedback.setText("That code does not match. Read every character and try again.");});Design.button(body,"Use Math instead",false,()->{if(closed||!current.getAsBoolean())return;if(!prefs.edit().putString("typeCodeMathOwner",key).commit()){feedback.setText("Math alternative could not be saved. Try again.");return;}close();fallback.run();});}
 Bundle state(){Bundle state=new Bundle();state.putString("typeCodeKey",key);state.putString("typeCodeAnswer",input.getText().toString());return state;}
 @Override public void close(){closed=true;}
 static final class CodeArt extends View{final TypeCodePuzzle puzzle;final Paint paint=new Paint(3);CodeArt(Context c,TypeCodePuzzle puzzle){super(c);this.puzzle=puzzle;setContentDescription("Challenge code: "+String.join(" ",puzzle.code.split("")));}protected void onDraw(Canvas canvas){super.onDraw(canvas);paint.setColor(Design.SOFT);canvas.drawRoundRect(0,0,getWidth(),getHeight(),Design.dp(getContext(),16),Design.dp(getContext(),16),paint);float padding=Design.dp(getContext(),12),cell=(getWidth()-padding*2)/puzzle.code.length();paint.setColor(0x228768a6);paint.setStrokeWidth(Design.dp(getContext(),1));for(int n=0;n<3;n++)canvas.drawLine(padding,getHeight()*(.28f+n*.21f),getWidth()-padding,getHeight()*(.38f+n*.12f),paint);paint.setTypeface(Design.font(getContext(),700));paint.setTextSize(Math.min(Design.dp(getContext(),42),cell*1.15f));paint.setTextAlign(Paint.Align.CENTER);java.util.Random random=new java.util.Random(puzzle.seed);for(int n=0;n<puzzle.code.length();n++){float x=padding+(n+.5f)*cell,y=getHeight()*.66f;canvas.save();canvas.rotate(random.nextInt(13)-6,x,getHeight()/2f);paint.setColor(n%2==0?Design.BROWN:0xff674496);canvas.drawText(puzzle.code.substring(n,n+1),x,y,paint);canvas.restore();}}}
}
